import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-forgot-password',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './forgot-password.component.html',
  styleUrls: ['./forgot-password.component.scss']
})
export class ForgotPasswordComponent {
  form: FormGroup;
  isLoading = false;
  hasError = false;
  successMessage = '';
  errorMessage = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {
    this.form = this.fb.group({
      email: ['', [Validators.required, Validators.email]]
    });
  }

  get email() {
    return this.form.get('email');
  }

  submit(): void {
    if (this.form.invalid || this.isLoading) {
      return;
    }

    this.isLoading = true;
    this.hasError = false;
    this.errorMessage = '';
    this.successMessage = '';

    this.authService.forgotPassword(this.form.value.email as string).subscribe({
      next: (response) => {
        this.successMessage = response.message;
        this.isLoading = false;
      },
      error: (error) => {
        this.hasError = true;
        this.errorMessage = error?.error?.message || 'Falha ao solicitar recuperacao de senha.';
        this.isLoading = false;
      }
    });
  }

  goToLogin(): void {
    this.router.navigate(['/login']);
  }
}
<div class="forgot-container">
  <div class="forgot-card">
    <h1>Recuperar senha</h1>
    <p>Informe seu email para receber instrucoes de redefinicao.</p>

    <form [formGroup]="form" (ngSubmit)="submit()" class="forgot-form">
      <label for="email">Email</label>
      <input id="email" type="email" formControlName="email" placeholder="seu@email.com" [class.error]="email?.invalid && email?.touched" />
      <small class="error" *ngIf="email?.errors?.['required'] && email?.touched">Email obrigatorio.</small>
      <small class="error" *ngIf="email?.errors?.['email'] && email?.touched">Email invalido.</small>

      <div class="alert success" *ngIf="successMessage">{{ successMessage }}</div>
      <div class="alert error" *ngIf="hasError">{{ errorMessage }}</div>

      <button type="submit" [disabled]="isLoading || form.invalid">
        <span *ngIf="!isLoading">Enviar</span>
        <span *ngIf="isLoading">Enviando...</span>
      </button>
    </form>

    <a href="javascript:void(0)" (click)="goToLogin()">Voltar para login</a>
  </div>
</div>
